/// Một từ vựng: từ tiếng Anh + phiên âm IPA + nghĩa tiếng Việt + 1 câu ví dụ
/// song ngữ. Nội dung tự biên soạn (không sao chép từ nguồn nào) - xem
/// docs/research-music-libraries.md không áp dụng ở đây vì đây không phải
/// nhạc; danh sách chủ đề chỉ tham khảo các chủ đề tiếng Anh giao tiếp phổ
/// biến (gia đình, thời tiết, mua sắm...) - đây là kiến thức chung, không
/// thuộc về bất kỳ nguồn cụ thể nào.
/// Muc do thong dung - dung de loc/sap xep tu de hoc truoc, tu hiem hoc sau.
/// [frequency] cua 1 tu la NHAN DINH chu quan (khong tra tu 1 kho ngu lieu
/// tan suat that) - xep theo muc do 1 nguoi hoc tieng Anh giao tiep thong
/// thuong co kha nang gap tu do trong doi song hang ngay.
enum VocabFrequency {
  common, // gap hang ngay (vd "mother", "water")
  medium, // gap thuong xuyen nhung khong co ban (vd "colleague", "umbrella")
  rare; // it gap, tu chuyen sau/trang trong (vd "sibling", "itinerary")

  String get labelKeyVi => switch (this) {
    common => 'vocab_frequency_common',
    medium => 'vocab_frequency_medium',
    rare => 'vocab_frequency_rare',
  };
}

/// Tu loai co ban - dung de loc theo phan loai (danh tu/dong tu/tinh tu...).
enum VocabPartOfSpeech {
  noun,
  verb,
  adjective,
  adverb,
  phrase;

  String get labelKey => switch (this) {
    noun => 'vocab_pos_noun',
    verb => 'vocab_pos_verb',
    adjective => 'vocab_pos_adjective',
    adverb => 'vocab_pos_adverb',
    phrase => 'vocab_pos_phrase',
  };
}

class VocabWord {
  const VocabWord({
    required this.en,
    required this.ipa,
    required this.vi,
    required this.exampleEn,
    required this.exampleVi,
    this.frequency,
    this.partOfSpeech,
  });

  final String en;
  final String ipa;
  final String vi;
  final String exampleEn;
  final String exampleVi;

  // Nullable vi phan lon tu cu (bien soan truoc khi co tinh nang phan loai
  // nay) CHUA duoc gan nhan - se bo sung dan, KHONG chan hien thi tu chua
  // phan loai (UI coi nhu "chua ro muc do/tu loai", van hien binh thuong o
  // che do xem "Tat ca").
  final VocabFrequency? frequency;
  final VocabPartOfSpeech? partOfSpeech;
}

class VocabTopic {
  const VocabTopic({
    required this.name,
    required this.nameEn,
    required this.icon,
    required this.color,
    required this.words,
  });

  final String name;

  /// Ten chu de bang tieng Anh - hien thi thay [name] khi ngon ngu giao
  /// dien la English (xem topicLabel() ben duoi).
  final String nameEn;
  final IconData icon;
  final Color color;
  final List<VocabWord> words;
}

/// Ten chu de theo ngon ngu giao dien hien tai - dung o moi noi hien thi
/// ten chu de (danh sach, man chi tiet, quiz) thay vi doc thang [VocabTopic.name].
String topicLabel(WidgetRef ref, VocabTopic topic) =>
    ref.watch(appLanguageProvider) == AppLanguage.en
    ? topic.nameEn
    : topic.name;

/// Danh sach day du (kem nghia/IPA) cac tu da danh dau "Da hoc" o man Tu
/// vung theo chu de - dung cho popup "Words Learned" mo tu the Hoat dong o
/// man Ho so (xem learned_words_popup.dart). Nguon DUY NHAT la
/// user_learned_words (qua StatsRepository.fetchLearnedWords, giu thu tu
/// hoc GAN DAY NHAT truoc) doi chieu lai voi [kVocabTopics] de lay nghia
/// hien thi - tu nao khong khop duoc (ly thuyet khong xay ra vi cung 1
/// nguon du lieu tu) se bi bo qua thay vi hien "null".
final learnedVocabWordsProvider = FutureProvider.autoDispose<List<VocabWord>>((
  ref,
) async {
  final userId = ref.watch(supabaseClientProvider).auth.currentUser?.id;
  if (userId == null) return const [];
  final learnedEn = await ref
      .watch(statsRepositoryProvider)
      .fetchLearnedWords();
  final byEn = <String, VocabWord>{
    for (final t in kVocabTopics)
      for (final w in t.words) w.en.toLowerCase(): w,
  };
  return [
    for (final en in learnedEn)
      if (byEn[en] != null) byEn[en]!,
  ];
});

